  "shahada": { src: "img/learn/shahada.webp", credit: "Public domain · Wikimedia Commons",
    alt: { en: "The Shahada in Arabic calligraphy", tr: "Arapça hat sanatıyla Kelime-i Şehadet", fr: "La Shahada en calligraphie arabe" } },
